CREATE TABLE model_derivations (
    model_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
    tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    workspace_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    preparation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    attempt_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    artifact_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE,
    base_model_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    review_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE,
    catalog_digest VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL CHECK(REGEXP_LIKE(catalog_digest,'^[a-f0-9]{64}$','c')),
    catalog JSON NOT NULL CHECK(JSON_TYPE(catalog)='OBJECT' AND OCTET_LENGTH(CAST(catalog AS CHAR CHARACTER SET utf8mb4))<=16384),
    report_sha256 VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL CHECK(REGEXP_LIKE(report_sha256,'^[a-f0-9]{64}$','c')),
    created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    CHECK(model_id=artifact_id AND model_id<>base_model_id),
    UNIQUE(tenant_id,workspace_id,model_id),
    FOREIGN KEY(tenant_id,workspace_id,model_id,catalog_digest) REFERENCES model_versions(tenant_id,workspace_id,id,catalog_digest),
    FOREIGN KEY(tenant_id,workspace_id,base_model_id) REFERENCES model_versions(tenant_id,workspace_id,id),
    FOREIGN KEY(tenant_id,workspace_id,review_id) REFERENCES model_preparation_reviews(tenant_id,workspace_id,id),
    FOREIGN KEY(tenant_id,workspace_id,preparation_id,attempt_id,artifact_id) REFERENCES model_preparation_artifacts(tenant_id,workspace_id,preparation_id,attempt_id,id),
    CONSTRAINT model_derivations_model_id_canonical CHECK(REGEXP_LIKE(model_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT model_derivations_tenant_id_canonical CHECK(REGEXP_LIKE(tenant_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT model_derivations_workspace_id_canonical CHECK(REGEXP_LIKE(workspace_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT model_derivations_preparation_id_canonical CHECK(REGEXP_LIKE(preparation_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT model_derivations_attempt_id_canonical CHECK(REGEXP_LIKE(attempt_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT model_derivations_artifact_id_canonical CHECK(REGEXP_LIKE(artifact_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT model_derivations_base_model_id_canonical CHECK(REGEXP_LIKE(base_model_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT model_derivations_review_id_canonical CHECK(REGEXP_LIKE(review_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
